// Local DiffSinger output is rendered from the exact note/lyric data in composition.js.
const vocalModeLabel=document.createElement('label');vocalModeLabel.innerHTML='演示声音<select id="performanceAudioMode"><option value="vocal">女声弹唱 · 原调原速</option><option value="piano">钢琴分轨 · 可移调慢练</option></select>';$('.performance-controls').prepend(vocalModeLabel);
const vocalCredit=document.createElement('p');vocalCredit.className='local-vocal-credit';vocalCredit.innerHTML='女声为 AI 歌声合成：<a href="https://github.com/yqzhishen/qixuan-diffsinger" target="_blank" rel="noopener">绮萱 · DiffSinger</a>，使用 OpenUtau 本地渲染。<a href="assets/original-song-female-vocal.mp3" download>下载女声干声</a> · <a href="assets/original-song-female-mix.mp3" download>下载完整弹唱</a> · <a href="assets/original-song-vocal-project.ustx" download>下载歌声工程</a>';$('.voice-notice').after(vocalCredit);
let localVocalBuffer=null,localVocalSource=null;
const pianoOnlyPlay=$('#performancePlay').onclick,preVocalStop=stopPerformance;
stopPerformance=function(){if(localVocalSource){try{localVocalSource.stop()}catch{}localVocalSource.disconnect();localVocalSource=null}preVocalStop()};
function configureVocalMode(){const singing=$('#performanceAudioMode').value==='vocal'&&performanceScore===composedSong;$('#performanceRoot').disabled=singing;$('#performanceTempo').disabled=singing;$('#performanceGuide').disabled=singing;if(singing){$('#performanceRoot').value='0';$('#performanceTempo').value='66';$('#performanceGuide').checked=false;$('.voice-notice').textContent='女声按这份谱逐字、逐音合成。演唱段播放女声与和弦伴奏；器乐段播放钢琴旋律。女声固定原调、66 BPM，慢练请切换钢琴分轨。'}else{$('.voice-notice').textContent='钢琴练习模式：可以调整调性、速度和旋律提示音。歌声录音保留在原调原速模式。'}renderPerformance()}
$('#performanceAudioMode').onchange=()=>{stopPerformance();configureVocalMode()};$('#performanceSong').addEventListener('change',()=>{if($('#performanceSong').value==='import')$('#performanceAudioMode').value='piano';configureVocalMode()});$('#scoreApply').addEventListener('click',()=>{if(performanceScore!==composedSong){$('#performanceAudioMode').value='piano';configureVocalMode()}});
async function getLocalVocal(){if(!localVocalBuffer){const response=await fetch('assets/original-song-female-vocal.mp3');if(!response.ok)throw Error('女声文件暂时无法加载');localVocalBuffer=await ctx.decodeAudioData(await response.arrayBuffer())}return localVocalBuffer}
$('#performancePlay').onclick=async()=>{if($('#performanceAudioMode').value!=='vocal'||performanceScore!==composedSong)return pianoOnlyPlay();if(performancePlaying)return;stopPerformance();stopSong();const run=performanceRun;$('#performanceState').textContent='正在载入本地合成女声…';let buffer;try{await audio();buffer=await getLocalVocal()}catch(e){$('#performanceState').textContent=e.message+'，可以切换钢琴模式试听';return}if(run!==performanceRun)return;
 const beat=60000/66,from=performanceBar,plan=songEventPlan(from,$('#arrangementMode').value,false),bars=flattenScore(),delay=150;performancePlaying=true;$('#performancePlay').disabled=true;$('#performanceStop').disabled=false;
 const source=ctx.createBufferSource();source.buffer=buffer;const gain=ctx.createGain();gain.gain.value=.85;source.connect(gain);gain.connect(ctx.destination);localVocalSource=source;source.onended=()=>gain.disconnect();source.start(ctx.currentTime+delay/1000,from*4*60/66);scoreClock={start:performance.now()+delay,beat,from};animateScore();
 for(let index=from;index<bars.length;index++)perfSchedule(()=>{perfBarUI(index);$('#performanceState').textContent=`女声弹唱 · 第 ${index+1} / ${bars.length} 小节 · ${bars[index].section}`},delay+(index-from)*4*beat);
 plan.events.forEach(e=>{perfSchedule(()=>{if(e.kind==='melody')$(`[data-perf-note="${e.bar}-${e.note}"]`)?.classList.add('playing');if(e.midi!==null&&(e.kind==='chord'||e.audible)){noteOn(e.id,e.midi-(octave+1)*12).then(()=>{const v=voices.get(e.id);if(v){const t=ctx.currentTime;v.g.gain.cancelScheduledValues(t);v.g.gain.setValueAtTime(0,t);v.g.gain.linearRampToValueAtTime(.065*e.gain,t+.025)}})}},delay+e.at*beat);perfSchedule(()=>{noteOff(e.id);if(e.kind==='melody')$(`[data-perf-note="${e.bar}-${e.note}"]`)?.classList.remove('playing')},delay+(e.at+e.duration)*beat)});
 perfSchedule(()=>{stopPerformance();$('#performanceState').textContent='女声弹唱完成 · 可选择小节重听'},delay+plan.duration*beat+250)};
// Original listeners may predate the vocal source wrapper; these close the source too.
window.addEventListener('blur',()=>stopPerformance());document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPerformance()});
configureVocalMode();
